-- data/actor_profiles.lua: one ActorProfile per actor archetype, merging:
--   repo actor_ai.lua `profiles` (package ids, action kind/code, movement/projectile flags) [repo; values match ROM below]
--   visual_profile_id: native adapter translation of actor +0x0E [C]
--   weapon           : stable item ID -> data/weapons.lua record (corp guard = max_power) [C]
--   reinforcement    : building spawn profile +0x10 used by the alarm spawner 0x1E04A (doc 20a §10) - per-building,
--                      so it lives on the building/run record, not here [C].
-- Generated by an inline script from the repo + rom.bin; regenerate rather than hand-edit.
local E = require("enums")
local VisualProfile = E.ActorVisualProfile

---@class ActorProfile
local ActorProfile = {}
ActorProfile.__index = ActorProfile
setmetatable(ActorProfile, { __call = function(_, t) return setmetatable(t, ActorProfile) end })
function ActorProfile:weapon_record() return self.weapon and require("data.weapons").get(self.weapon) or nil end
function ActorProfile:is_armed() return self.weapon ~= nil end

local M = { ActorProfile = ActorProfile, by_id = {
    ["corp_guard_k05_item06"] = ActorProfile{ id = "corp_guard_k05_item06", package_id = "corp_security.max_power_heavy_pistol", visual_profile_id = VisualProfile.HUMAN_GUARD, action_kind = "item", weapon = "max_power", controls_movement = false, projectile = false, dynamic_encounter_only = false },
    ["pedestrian_k0b_none00"] = ActorProfile{ id = "pedestrian_k0b_none00", package_id = "pedestrian.no_active_action", visual_profile_id = VisualProfile.PEDESTRIAN_RAT_SHAMAN, action_kind = "none", weapon = nil, controls_movement = false, projectile = false, dynamic_encounter_only = false },
    ["field_runner_k03_none00"] = ActorProfile{ id = "field_runner_k03_none00", package_id = "runner.field_controlled", visual_profile_id = VisualProfile.FIELD_RUNNER, action_kind = "none", weapon = nil, controls_movement = true, projectile = false, dynamic_encounter_only = false },
    ["hell_hound_k0c_none00"] = ActorProfile{ id = "hell_hound_k0c_none00", package_id = "creature.hell_hound.source_target_motion", visual_profile_id = VisualProfile.HELL_HOUND, action_kind = "none", weapon = nil, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["gargoyle_k0d_none00"] = ActorProfile{ id = "gargoyle_k0d_none00", package_id = "creature.gargoyle.source_target_motion", visual_profile_id = VisualProfile.GARGOYLE, action_kind = "none", weapon = nil, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["wendigo_k0e_none00"] = ActorProfile{ id = "wendigo_k0e_none00", package_id = "creature.wendigo.source_target_motion", visual_profile_id = VisualProfile.WENDIGO, action_kind = "none", weapon = nil, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["weapon_projectile"] = ActorProfile{ id = "weapon_projectile", package_id = "combat.weapon_projectile", visual_profile_id = nil, action_kind = "none", weapon = nil, controls_movement = false, projectile = true, dynamic_encounter_only = false },
    ["field_hit_spark"] = ActorProfile{ id = "field_hit_spark", package_id = "combat.player_hit_spark", visual_profile_id = VisualProfile.HIT_SPARK, action_kind = "none", weapon = nil, controls_movement = false, projectile = false, dynamic_encounter_only = false },
} }
-- Dynamic profiles receive named visual and action identities from the host.
function M.dynamic(visual_profile_id, action_kind, action_id)
    local identity = action_id or "none"
    return ActorProfile{ id = "dynamic." .. visual_profile_id .. "." .. action_kind .. "." .. identity,
        visual_profile_id = visual_profile_id, action_kind = action_kind, action_id = action_id,
        weapon = action_kind == "item" and action_id or nil,
        controls_movement = visual_profile_id ~= VisualProfile.THON,
        projectile = false, dynamic_encounter_only = true }
end
return M
